mapper.select:
SELECT u.id, u.tenant_id, t.name AS tenant_name, u.username, u.nickname, u.real_name, u.gender, u.avatar, u.phone, u.email, u.realm, u.is_superadmin, u.status, u.status_time, u.status_reason, u.login_fail_count, u.must_change_password, u.password_update_time, u.effective_start_time, u.effective_end_time, u.last_login_ip, u.last_login_time, u.is_builtin, u.source_type, u.remark, u.version, u.create_time, u.update_time, u.create_by, u.update_by, d.dept_names, r.role_names FROM sys_user u
LEFT JOIN sys_tenant t ON t.id = u.tenant_id AND t.is_deleted = 0
LEFT JOIN ( SELECT ud.user_id, GROUP_CONCAT(d.name ORDER BY d.sort SEPARATOR ', ') AS dept_names FROM sys_user_dept ud INNER JOIN sys_dept d ON d.id = ud.dept_id AND d.is_deleted = 0 WHERE ud.is_deleted = 0 GROUP BY ud.user_id ) d ON d.user_id = u.id
LEFT JOIN ( SELECT ur.user_id, GROUP_CONCAT(r.name ORDER BY r.sort SEPARATOR ', ') AS role_names FROM sys_user_role ur INNER JOIN sys_role r ON r.id = ur.role_id AND r.is_deleted = 0 WHERE ur.is_deleted = 0 GROUP BY ur.user_id ) r ON r.user_id = u.id WHERE u.is_deleted = 0 AND u.tenant_id = #{tenantId}
AND u.realm = #{request.realm}
AND EXISTS ( SELECT 1 FROM sys_user_dept ud2 WHERE ud2.user_id = u.id AND ud2.dept_id = #{request.deptId} AND ud2.is_deleted = 0 )
AND (u.username LIKE CONCAT('%', #{request.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{request.keyword}, '%') OR u.real_name LIKE CONCAT('%', #{request.keyword}, '%') OR u.phone LIKE CONCAT('%', #{request.keyword}, '%') OR u.email LIKE CONCAT('%', #{request.keyword}, '%'))
AND u.username LIKE CONCAT('%', #{request.username}, '%')
AND u.nickname LIKE CONCAT('%', #{request.nickname}, '%')
AND u.status = #{request.status}
ORDER BY ${request.safeSortField()} ${request.safeSortOrder()}
ORDER BY u.create_time DESC
